107	class OpKernel {
108	 public:
109	  // OpKernel won't be instantiated by the scheduler, so you may perform
110	  // expensive initialization in the descendant's constructor.
111	  explicit OpKernel(OpKernelConstruction* context);
112	
113	  // Specialized constructor that allows a kernel implementation to mark itself
114	  // as a "deferred" op. If true, the executor will provide access to the
115	  // `OpKernelContext::inc_num_deferred_ops_function()` and
116	  // `OpKernelContext::dec_num_deferred_ops_function()` methods at run-time.
117	  OpKernel(OpKernelConstruction* context, bool is_deferred);
118	
119	  // Specialized constructor that enables the descendant to provide a custom
120	  // `NodeDef` value. For example, this constructor can be used to provide a
121	  // stripped-down `NodeDef` that does not contain the full set of attrs (such
122	  // as tensor values) if the descendant stores them in a different form.
123	  OpKernel(OpKernelConstruction* context, NodeDef&& custom_def,
124	           bool is_deferred);
125	
126	  virtual ~OpKernel();
127	
128	  // An OpKernel's computation can be either synchronous or
129	  // asynchronous. All OpKernel Compute() methods must be thread-safe as they
130	  // may be called concurrently (e.g. by multiple executions of the same graph
131	  // concurrently).
132	  //
133	  // Most OpKernels should compute synchronously. They should
134	  // subclass OpKernel and override the Compute() method and have it
135	  // return after completing the supplied work.
136	  //
137	  // A synchronous OpKernel *MUST NOT* block the calling thread on a
138	  // synchronization mechanism (condition variable, Notification, etc.) that
139	  // will be unblocked by the execution of another OpKernel. Execution may
140	  // deadlock in that case, because the executor may use a bounded number of
141	  // threads.
142	  //
143	  // If an OpKernel must block on the execution of another OpKernel (e.g. a
144	  // RecvOp, or a DequeueOp), the implementation *MUST* subclass AsyncOpKernel,
145	  // and override `AsyncOpKernel::ComputeAsync()`. In addition, because the
146	  // unblocking kernel may never run (due to an error or cancellation), in most
147	  // cases the AsyncOpKernel should implement cancellation support via
148	  // `ctx->cancellation_manager()`.
149	  //
150	  // In both cases, implementations of Compute() and ComputeAsync()
151	  // get inputs and write outputs through the given OpKernelContext
152	  // and returns a status via context->SetStatus(). They must be
153	  // thread-safe.
154	
155	  // Synchronous compute.
156	  //
157	  // "context" is guaranteed to be alive until Compute() returns.
158	  virtual void Compute(OpKernelContext* context) = 0;
159	
160	  // Returns nullptr iff this op kernel is synchronous.
161	  virtual AsyncOpKernel* AsAsync() { return nullptr; }
162	
163	  // Returns true iff this op kernel is considered "expensive". The
164	  // runtime may use this flag to optimize graph execution for example
165	  // to "inline" inexpensive kernels.
166	  virtual bool IsExpensive() { return expensive_; }
167	
168	  // Returns a pointer to the tensor stored inside constant ops.
169	  virtual const Tensor* const_tensor() const { return nullptr; }
170	
171	  // Accessors.
172	  const NodeDef& def() const { return props_->node_def; }
173	  const std::string& name() const { return props_->node_def.name(); }
174	  absl::string_view name_view() const { return name_view_; }
175	  const std::string& type_string() const { return props_->node_def.op(); }
176	  absl::string_view type_string_view() const { return type_string_view_; }
177	  const std::string& requested_input(int i) const {
178	    return props_->node_def.input(i);
179	  }
180	  const std::string& requested_device() const {
181	    return props_->node_def.device();
182	  }
183	
184	  int num_inputs() const { return props_->input_types.size(); }
185	  DataType input_type(int i) const { return props_->input_types[i]; }
186	  const DataTypeVector& input_types() const { return props_->input_types; }
187	  const MemoryTypeVector& input_memory_types() const {
188	    return input_memory_types_;
189	  }
190	
191	  int num_outputs() const { return props_->output_types.size(); }
192	  DataType output_type(int o) const { return props_->output_types[o]; }
193	  const DataTypeVector& output_types() const { return props_->output_types; }
194	  const MemoryTypeVector& output_memory_types() const {
195	    return output_memory_types_;
196	  }
197	
198	  absl::Status InputRange(absl::string_view input_name, int* start,
199	                          int* stop) const;
200	  absl::Status OutputRange(absl::string_view output_name, int* start,
201	                           int* stop) const;
202	
203	  // Returns `true` if and only if this kernel uses deferred execution.
204	  bool is_deferred() const { return is_deferred_; }
205	
206	  // Returns a trace string for current computation, op name/type and input
207	  // tensor shape/dtype are encoded for profiler cost analysis. Most OpKernel
208	  // should use the default implementation.
209	  virtual std::string TraceString(const OpKernelContext& ctx,
210	                                  bool verbose) const;
211	
212	 protected:
213	  std::string ShapeTraceString(const OpKernelContext& ctx) const;
214	
215	 private:
216	  const std::shared_ptr<const NodeProperties> props_;
217	  const MemoryTypeVector input_memory_types_;
218	  const MemoryTypeVector output_memory_types_;
219	  NameRangeMap input_name_map_;
220	  NameRangeMap output_name_map_;
221	  const absl::string_view name_view_;
222	  const absl::string_view type_string_view_;
223	  const int graph_def_version_;
224	  const bool is_deferred_;
225	  bool expensive_;
226	
227	  OpKernel(const OpKernel&) = delete;
228	  void operator=(const OpKernel&) = delete;
229	};
