231	class AsyncOpKernel : public OpKernel {
232	 public:
233	  using OpKernel::OpKernel;  // Lift OpKernel constructors.
234	
235	  // Asynchronous compute.
236	  //
237	  // Implementations of ComputeAsync() must ensure that `done` is (eventually)
238	  // called exactly once to signal the completion of the computation. The
239	  // implementation of ComputeAsync() must not block on the execution of another
240	  // OpKernel. `done` may be called by the current thread, or by another thread.
241	  // `context` is guaranteed to stay alive until the `done` callback starts.
242	  //
243	  // Since it is possible that the unblocking kernel may never run (due to an
244	  // error or cancellation), in most cases the AsyncOpKernel should implement
245	  // cancellation support via `context->cancellation_manager()`.
246	  //
247	  // WARNING: As soon as the `done` callback starts, `context` and `this` may be
248	  // deleted. No code depending on these objects should execute after the call
249	  // to `done`.
250	  typedef std::function<void()> DoneCallback;
251	  virtual void ComputeAsync(OpKernelContext* context, DoneCallback done) = 0;
252	
253	  AsyncOpKernel* AsAsync() override { return this; }
254	
255	  void Compute(OpKernelContext* context) override;
256	};
