258	class OpKernelConstruction {
259	 public:
260	  OpKernelConstruction(DeviceType device_type, DeviceBase* device,
261	                       Allocator* allocator, FunctionLibraryRuntime* flib,
262	                       ResourceMgr* resource_mgr,
263	                       const std::shared_ptr<const NodeProperties>& props,
264	                       const MemoryTypeSlice& input_memory_types,
265	                       const MemoryTypeSlice& output_memory_types,
266	                       int graph_def_version, absl::Status* status);
267	
268	  Env* env() const { return device_->env(); }
269	
270	  // Allocation of tensors during kernel construction:
271	  //
272	  // It is legal to temporarily allocate scratch tensor storage during
273	  // Op kernel construction. Scratch tensors should be allocated using
274	  // allocate_temp below. Some kernels need to keep tensors in between
275	  // invocations. If such a Tensor is allocated during kernel
276	  // construction this also must be done using allocate_temp, and the
277	  // Op may only store the returned Tensor object.
278	
279	  // Allocates a temporary Tensor of the specified type and shape. The
280	  // Tensor must not be used after kernel construction is
281	  // complete. See comment above.
282	  absl::Status allocate_temp(DataType type, const TensorShape& shape,
283	                             Tensor* out_temp);
284	  absl::Status allocate_temp(DataType type, const TensorShape& shape,
285	                             Tensor* out_temp,
286	                             AllocatorAttributes allocator_attr);
287	
288	  // User-supplied configuration of this operation.
289	  const NodeDef& def() const { return props_->node_def; }
290	
291	  // For inspecting the inputs to this operation.
292	  int num_inputs() const { return props_->input_types.size(); }
293	  DataType input_type(int i) const { return props_->input_types[i]; }
294	  const DataTypeSlice& input_types() const { return props_->input_types_slice; }
295	  const MemoryTypeSlice& input_memory_types() const {
296	    return input_memory_types_;
297	  }
298	
299	  // For inspecting the outputs expected from this operation.
300	  int num_outputs() const { return props_->output_types.size(); }
301	  DataType output_type(int i) const { return props_->output_types[i]; }
302	  const DataTypeSlice& output_types() const {
303	    return props_->output_types_slice;
304	  }
305	  const MemoryTypeSlice& output_memory_types() const {
306	    return output_memory_types_;
307	  }
308	
309	  // If expected_inputs == inputs() and expected_outputs == output_types(),
310	  // returns OK, else returns INVALID_ARGUMENT with an error message.
311	  // Recommended for Ops with dynamic signatures.
312	  absl::Status MatchSignature(const DataTypeSlice expected_inputs,
313	                              const DataTypeSlice expected_outputs);
314	
315	  // For recording configuration errors during construction.
316	  void SetStatus(const absl::Status& status);
317	  const absl::Status& status() const { return *status_; }
318	
319	  // Look up the attr with name attr_name and set *value to its value.  If no
320	  // attr with attr_name is found in def(), or the attr does not have
321	  // a matching type, a non-ok status will be returned.
322	  template <class T>
323	  absl::Status GetAttr(absl::string_view attr_name,
324	                       T* value) const TF_ATTRIBUTE_NOINLINE;
325	
326	  // Return true if the attr_name is defined in def().
327	  bool HasAttr(absl::string_view attr_name) const;
328	
329	  // Return the device type.
330	  const DeviceType& device_type() const { return device_type_; }
331	
332	  // If not nullptr, the kernel can instantiate functions defined in
333	  // the library. E.g.,
334	  // CHECK_NOTNULL(function_library())->Instantiate("Foo", ...).
335	  FunctionLibraryRuntime* function_library() const { return flib_; }
336	
337	  // Shared resources accessible to this kernel.
338	  ResourceMgr* resource_manager() const { return resource_mgr_; }
339	
340	  // The GraphDef version whose behavior we should follow.
341	  int graph_def_version() const { return graph_def_version_; }
342	
343	  // Helper routines for the OP_REQUIRES macros
344	  void CtxFailure(const absl::Status& s);
345	  void CtxFailureWithWarning(const absl::Status& s);
346	  void CtxFailure(const char* file, int line, const absl::Status& s);
347	  void CtxFailureWithWarning(const char* file, int line, const absl::Status& s);
348	
349	  // Unrecommended functions: these are functions that have some
350	  // current uses but are not recommended for use, and may go away at
351	  // some future major version release.
352	
353	  // May be used, e.g., to get GPU handles, etc.
354	  //
355	  // Currently only used to call MakeTensorFromProto() for
356	  // implementing ConstantOp for every device.  See comments
357	  // on Device::MakeTensorFromProto for longer-term replacement
358	  // ideas.
359	  DeviceBase* device() const { return device_; }
360	
361	 private:
362	  const DeviceType device_type_;
363	  DeviceBase* const device_;
364	  Allocator* allocator_;
365	  FunctionLibraryRuntime* flib_;
366	  ResourceMgr* const resource_mgr_;
367	  std::shared_ptr<const NodeProperties> props_;
368	  MemoryTypeSlice input_memory_types_;
369	  MemoryTypeSlice output_memory_types_;
370	  const int graph_def_version_;
371	  absl::Status* status_;
372	
373	  // Allow access from OpKernel ctor.
374	  friend class OpKernel;
375	
376	  OpKernelConstruction(const OpKernelConstruction&) = delete;
377	  void operator=(const OpKernelConstruction&) = delete;
378	};
