380	// TODO(mrry): Consider converting to a random_access_iterator, and upgrading
381	// tensorflow::gtl::iterator_range to make the below container classes
382	// unnecessary.
383	template <typename ListType, typename ElementType>
384	class OpArgIterator {
385	 public:
386	  using iterator_category = std::forward_iterator_tag;
387	  using value_type = ElementType;
388	  using pointer = ElementType*;
389	  using const_pointer = const ElementType*;
390	  using reference = ElementType&;
391	  using const_reference = const ElementType&;
392	  using difference_type = ptrdiff_t;
393	
394	  OpArgIterator(const ListType* list, int i) : list_(list), i_(i) {}
395	
396	  bool operator==(const OpArgIterator& rhs) {
397	    DCHECK(list_ == rhs.list_);
398	    return i_ == rhs.i_;
399	  }
400	
401	  bool operator!=(const OpArgIterator& rhs) {
402	    DCHECK(list_ == rhs.list_);
403	    return i_ != rhs.i_;
404	  }
405	
406	  OpArgIterator operator++() {  // prefix ++it
407	    ++i_;
408	    return *this;
409	  }
410	
411	  OpArgIterator operator++(int) {  // postfix it++
412	    OpArgIterator old_value = *this;
413	    ++i_;
414	    return old_value;
415	  }
416	
417	  reference operator*() { return (*list_)[i_]; }
418	  pointer operator->() { return &(*list_)[i_]; }
419	
420	  const_reference operator*() const { return (*list_)[i_]; }
421	  const_pointer operator->() const { return &(*list_)[i_]; }
422	
423	 private:
424	  const ListType* const list_;
425	  int i_;
426	};
