495	// Holds a tensor or tensor reference. For tensor references, we need
496	// a mutex to prevent concurrent access to the tensor.
497	struct TensorValue {
498	  TensorValue() : mutex_if_ref(nullptr), tensor(nullptr) {}
499	  explicit TensorValue(Tensor* t) : mutex_if_ref(nullptr), tensor(t) {}
500	  TensorValue(mutex* mu, Tensor* t) : mutex_if_ref(mu), tensor(t) {}
501	  Tensor* operator->() const { return tensor; }
502	  bool is_ref() const { return mutex_if_ref != nullptr; }
503	
504	  // Return the dtype of the Tensor. For references, return the underlying type.
505	  DataType dtype() const {
506	    if (is_ref()) {
507	      return MakeRefType(tensor->dtype());
508	    } else {
509	      return tensor->dtype();
510	    }
511	  }
512	
513	  // Return the dtype of the Tensor. For references, return the underlying type.
514	  // This variation on the dtype() acquires the lock for references.
515	  //
516	  // TODO(b/133843385): Disallow dtype modifications
517	  DataType dtype_safe() const {
518	    if (is_ref()) {
519	      tf_shared_lock ml(*mutex_if_ref);
520	      return MakeRefType(tensor->dtype());
521	    } else {
522	      return tensor->dtype();
523	    }
524	  }
525	
526	  mutex* mutex_if_ref;  // nullptr if not a ref, != nullptr if a ref
527	  Tensor* tensor;
528	};
