530	// Used to store partitioned graphs from function-calling ops.
531	struct GraphCollector {
532	  mutex mu;
533	  std::vector<GraphDef> partitioned_graphs TF_GUARDED_BY(mu);
534	  GraphDef raw_graph TF_GUARDED_BY(mu);
535	  GraphDef optimized_graph TF_GUARDED_BY(mu);
536	
537	  bool dirty TF_GUARDED_BY(mu);
538	
539	  GraphCollector() : dirty(false) {}
540	
541	  void CollectRawGraph(const GraphDef& graph) {
542	    mutex_lock ml(mu);
543	    raw_graph.MergeFrom(graph);
544	    dirty = true;
545	  }
546	
547	  void CollectOptimizedGraph(const GraphDef& graph) {
548	    mutex_lock ml(mu);
549	    optimized_graph.MergeFrom(graph);
550	    dirty = true;
551	  }
552	
553	  void CollectPartitionedGraph(const GraphDef& graph) {
554	    mutex_lock ml(mu);
555	    partitioned_graphs.push_back(graph);
556	    dirty = true;
557	  }
558	
559	  void ClearGraphs() TF_EXCLUSIVE_LOCKS_REQUIRED(mu) {
560	    raw_graph.Clear();
561	    optimized_graph.Clear();
562	    partitioned_graphs.clear();
563	    dirty = false;
564	  }
565	
566	  bool HasUpdatedGraphs() {
567	    mutex_lock ml(mu);
568	    return dirty;
569	  }
570	};
