572	class OpKernelContext {
573	 public:
574	  // The first element of a WrappedAllocator is a "base" Allocator and
575	  // the second element is that Allocator wrapped by a
576	  // TrackingAllocator
577	  typedef std::pair<Allocator*, TrackingAllocator*> WrappedAllocator;
578	
579	  // TODO(zhifengc): Do some cleanup of Params.
580	  // The Params struct is passed in to initialize an OpKernelContext,
581	  // and must outlive the OpKernelContext.
582	  struct Params {
583	    ~Params() { delete eigen_gpu_device; }
584	
585	    // The step being executed.
586	    int64_t step_id = 0;
587	
588	    // Timestamp for the start of graph execution. Used for latency metrics.
589	    int64_t start_time_usecs = 0;
590	
591	    // The deadline for the session to complete by. Empty if unspecified.
