612	    inline void ensure_eigen_gpu_device() {
613	      DCHECK(device);
614	      if (nullptr == eigen_gpu_device) {
615	        // Surprisingly, MakeGpuDevice will return nullptr if the
616	        // device is not a GPU device. This is ok, since those devices
617	        // will never use eigen_gpu_device. It seems better to have
618	        // ensure_eigen_gpu_device fall through and regenerate the
619	        // nullptr every time an OpKernelContext is instantiated, than
620	        // to do an unnecessary allocation of a dummy eigen GPU
621	        // device for CPU device Ops.
622	        eigen_gpu_device = device->MakeGpuDevice();
623	      }
624	    }
