961	  // Allocation of tensors during kernel execution inside the Compute
962	  // method:
963	  //
964	  // There are two methods to allocate Tensors when an Op kernel
965	  // executes.
966	  //
967	  // 1) allocate_output. This should be used to allocate any tensor
968	  // that is going to be used as an output from the Op at the end of
969	  // the current execution. The caller indicates which output the
970	  // Tensor will be assigned to, and the call returns the
971	  // newly-allocated Tensor. The Tensor can subsequently be assigned
972	  // to during kernel execution, and will be used as the designated
973	  // output when the kernel execution completes.
974	  //
975	  // 2) allocate_temp. This should be used to allocate any scratch
976	  // storage that is needed while the kernel is executing, and will
977	  // not be retained by the Op.
978	  //
979	  // In some cases a Tensor needs to be used as an output even though
980	  // it was previously allocated elsewhere. The Tensor may have been
981	  // passed as an input, or stored in a Tensor during a
982	  // previous kernel execution, or allocated earlier in the kernel
983	  // execution at a time when it was not known which output it would
984	  // be assigned to. In this case the kernel can use set_output or
985	  // set_output_ref to indicate that the tensor should be used as the
986	  // designated output. It is legal to use any previously-allocated
987	  // Tensor as an argument to set_output or set_output_ref, including
988	  // Tensors allocated via allocate_temp. There may be a performance
989	  // penalty to using a Tensor that was not allocated using
990	  // allocate_output. This is because allocate_output uses the
991	  // AllocatorAttributes stored in output_attr_array for the
992	  // designated output. In some cases, using the wrong attributes may
993	  // cause an extra copy of the Tensor's buffer.
994	
995	  // Allocates output for the specified output index with shape.
996	  // OpKernelContext retains ownership of the returned pointer. See
997	  // comment above.
998	  //
999	  // If memory allocation fails, returns an error status.
1000	  //
1001	  // REQUIRES: !IsRefType(expected_output_dtype(index))
1002	  virtual absl::Status allocate_output(int index, const TensorShape& shape,
1003	                                       Tensor** tensor);
1004	  virtual absl::Status allocate_output(absl::string_view name,
1005	                                       const TensorShape& shape,
1006	                                       Tensor** tensor);
1007	  // The following methods use the supplied attributes instead of
1008	  // those in output_attr_array. The caller is responsible for
1009	  // ensuring that the attributes are "compatible" with the
1010	  // output_attr_array, e.g. the tensor is allocated on the correct
1011	  // device. See comment above.
1012	  virtual absl::Status allocate_output(int index, const TensorShape& shape,
1013	                                       Tensor** tensor,
1014	                                       AllocatorAttributes attr);
1015	  virtual absl::Status allocate_output(absl::string_view name,
1016	                                       const TensorShape& shape,
1017	                                       Tensor** tensor,
1018	                                       AllocatorAttributes attr);
