1355	// kernel runs on, any type attr constraints for this kernel, any
1356	// host-memory args, and the class to instantiate.  Examples:
1357	//
1358	//  // A kernel that supports all types.
1359	//  REGISTER_KERNEL_BUILDER(Name("Save").Device(DEVICE_CPU), SaveOp);
1360	//
1361	//  // The following are equivalent ways of specifying that the kernel only
1362	//  // works if the "T" type attr is set to DT_FLOAT.
1363	//  REGISTER_KERNEL_BUILDER(
1364	//      Name("Sub").Device(DEVICE_CPU).TypeConstraint<float>("T"),
1365	//      SubOp<float>);
1366	//  // (You would then repeat this for every type supported by "Sub".)
1367	//
1368	//  // This form allows you to specify a list of types as the constraint.
1369	//  REGISTER_KERNEL_BUILDER(Name("Sub")
1370	//                              .Device(DEVICE_CPU)
1371	//                              .TypeConstraint("T", {DT_FLOAT}),
1372	//                          SubOp<float>);
1373	//
1374	//  // A kernel that expects one of the input tensors in host memory.
1375	//  REGISTER_KERNEL_BUILDER(
1376	//      Name("Reshape").Device(DEVICE_GPU).HostMemory("shape"), ReshapeOp);
1377	//
1378	//  // A kernel that works on any device. Kernels using DEVICE_DEFAULT
1379	//  // must aways run on host and all inputs and outputs must use `HostMemory`.
1380	//  // Kernels for data management, control-flow primitives or working with
1381	//  // tensor shapes for various devices (including `PluggableDevices`) are
1382	//  // typical uses.
1383	//  REGISTER_KERNEL_BUILDER(
1384	//     Name("TensorListLength").Device(DEVICE_DEFAULT).HostMemory("length"),
1385	//     TensorListLength);
1386	//
