1437	// Allow the REGISTER_KERNEL_BUILDER(Name("op_name").Device(...)...) syntax.
1438	namespace register_kernel {
1439	
1440	class Name : public KernelDefBuilder {
1441	 public:
1442	  explicit Name(const char* op);
1443	};
