1447	// Kernel registration appears as:
1448	//   REGISTER_KERNEL_BUILDER(Name("OpName").Device(DEVICE_CPU)..., OpImpl)
1449	// We'd like to have "OpName" as a constant-expression, without requiring that
1450	// of the overall KernelDefBuilder expression (beginning with the
1451	// register_kernel::Name constructor above).
1452	//
1453	// So, we pull the "OpName" part to a separate macro-level argument. This
1454	// involves treating Name("OpName") as a macro call, via token-pasting (e.g.
1455	// M_## =>  M_Name("OpName")), and having it expand to '"OpName",
1456	// Name("OpName")' which is then usable as two arguments.
1457	#define TF_EXTRACT_KERNEL_NAME_Name(name_str) \
1458	  name_str, ::tensorflow::register_kernel::Name(name_str)
1459	#define TF_EXTRACT_KERNEL_NAME_IMPL(m, ...) m(__VA_ARGS__)
1460	#define TF_EXTRACT_KERNEL_NAME(m, kernel_builder, ...)                    \
1461	  TF_EXTRACT_KERNEL_NAME_IMPL(m, TF_EXTRACT_KERNEL_NAME_##kernel_builder, \
1462	                              __VA_ARGS__)
1463	
1464	// REGISTER_KERNEL_BUILDER_IMPL_2, with a unique 'ctr' as the first argument.
1465	// TODO(dodgen): There are some uses of this macro inside functions, where
1466	// kernel_builder refers to (non-const) locals (they should be fixed). To
1467	// accommodate those, kernel_builder.Build() appears as an argument to an
1468	// immediately-called lambda (not in the lambda itself).
1469	#define REGISTER_KERNEL_BUILDER_IMPL_3(ctr, op_name, kernel_builder_expr,   \
1470	                                       is_system_kernel, ...)               \
1471	  static ::tensorflow::InitOnStartupMarker const register_kernel_##ctr      \
1472	      TF_ATTRIBUTE_UNUSED =                                                 \
1473	          TF_INIT_ON_STARTUP_IF(is_system_kernel ||                         \
1474	                                (SHOULD_REGISTER_OP_KERNEL(#__VA_ARGS__) && \
1475	                                 SHOULD_REGISTER_OP(op_name)))              \
1476	          << ([](::tensorflow::KernelDef const* kernel_def) {               \
1477	               ::tensorflow::kernel_factory::OpKernelRegistrar registrar(   \
1478	                   kernel_def, #__VA_ARGS__,                                \
1479	                   [](::tensorflow::OpKernelConstruction* context)          \
1480	                       -> ::tensorflow::OpKernel* {                         \
1481	                     return new __VA_ARGS__(context);                       \
1482	                   });                                                      \
1483	               (void)registrar;                                             \
1484	               LOG_KERNEL_SOURCES(op_name)                                  \
1485	               return ::tensorflow::InitOnStartupMarker{};                  \
1486	             })(kernel_builder_expr.Build());
1487	
1488	// REGISTER_KERNEL_BUILDER_IMPL, but with kernel_builder split to op_name,
1489	// kernel_builder_expr.
1490	#define REGISTER_KERNEL_BUILDER_IMPL_2(op_name, kernel_builder_expr, \
1491	                                       is_system_kernel, ...)        \
1492	  TF_NEW_ID_FOR_INIT(REGISTER_KERNEL_BUILDER_IMPL_3, op_name,        \
1493	                     kernel_builder_expr, is_system_kernel, __VA_ARGS__)
1494	
1495	// REGISTER_KERNEL_BUILDER, but with is_system_kernel bound.
1496	#define REGISTER_KERNEL_BUILDER_IMPL(kernel_builder, is_system_kernel, ...) \
1497	  TF_EXTRACT_KERNEL_NAME(REGISTER_KERNEL_BUILDER_IMPL_2, kernel_builder,    \
1498	                         is_system_kernel, __VA_ARGS__)
1499	
1500	#define REGISTER_KERNEL_BUILDER(kernel_builder, ...) \
1501	  TF_ATTRIBUTE_ANNOTATE("tf:kernel")                 \
1502	  REGISTER_KERNEL_BUILDER_IMPL(kernel_builder, false, __VA_ARGS__)
1503	
1504	// The `REGISTER_SYSTEM_KERNEL_BUILDER()` macro acts as
1505	// `REGISTER_KERNEL_BUILDER()` except that the kernel is registered
1506	// unconditionally even when selective registration is used.
1507	#define REGISTER_SYSTEM_KERNEL_BUILDER(kernel_builder, ...) \
1508	  TF_ATTRIBUTE_ANNOTATE("tf:kernel")                        \
1509	  TF_ATTRIBUTE_ANNOTATE("tf:kernel:system")                 \
1510	  REGISTER_KERNEL_BUILDER_IMPL(kernel_builder, true, __VA_ARGS__)
