1572	class OpKernelRegistrar {
1573	 public:
1574	  // Registers the given kernel factory with TensorFlow. TF will call the
1575	  // factory Create() method when it determines that a kernel matching the given
1576	  // KernelDef is required.
1577	  OpKernelRegistrar(
1578	      const KernelDef* kernel_def, absl::string_view kernel_class_name,
1579	      std::unique_ptr<OpKernelFactory> factory) TF_ATTRIBUTE_NOINLINE {
1580	    InitInternal(kernel_def, kernel_class_name, std::move(factory));
1581	  }
1582	
1583	  // Registers the given factory function with TensorFlow. This is equivalent
1584	  // to registering a factory whose Create function invokes `create_fn`.
1585	  OpKernelRegistrar(
1586	      const KernelDef* kernel_def, absl::string_view kernel_class_name,
1587	      OpKernel* (*create_fn)(OpKernelConstruction*)) TF_ATTRIBUTE_NOINLINE {
1588	    InitInternal(kernel_def, kernel_class_name,
1589	                 std::make_unique<PtrOpKernelFactory>(create_fn));
1590	  }
1591	
1592	 private:
1593	  struct PtrOpKernelFactory : public OpKernelFactory {
1594	    explicit PtrOpKernelFactory(OpKernel* (*create_func)(OpKernelConstruction*))
1595	        : create_func_(create_func) {}
1596	
1597	    OpKernel* Create(OpKernelConstruction* context) override;
1598	
1599	    OpKernel* (*create_func_)(OpKernelConstruction*);
1600	  };
