1397	void OpKernelRegistrar::InitInternal(const KernelDef* kernel_def,
1398	                                     absl::string_view kernel_class_name,
1399	                                     std::unique_ptr<OpKernelFactory> factory) {
1400	  const std::string key =
1401	      Key(kernel_def->op(), DeviceType(kernel_def->device_type()),
1402	          kernel_def->label());
1403	
1404	  // To avoid calling LoadDynamicKernels DO NOT CALL GlobalKernelRegistryTyped
1405	  // here.
1406	  // InitInternal gets called by static initializers, so it ends up executing
1407	  // before main. This causes LoadKernelLibraries function to get called
1408	  // before some file libraries can initialize, which in turn crashes the
1409	  // program flakily. Until we get rid of static initializers in kernel
1410	  // registration mechanism, we have this workaround here.
1411	  auto global_registry =
1412	      reinterpret_cast<KernelRegistry*>(GlobalKernelRegistry());
1413	  mutex_lock l(global_registry->mu);
1414	  global_registry->registry.emplace(
1415	      key,
1416	      KernelRegistration(*kernel_def, kernel_class_name, std::move(factory)));
1417	  global_registry->version.fetch_add(1);
1418	  delete kernel_def;
1419	}
