1431	const std::string& GetKernelLabelAttr(const AttrSlice& node_attrs) {
1432	  static const std::string& kKernelAttr = *new std::string("_kernel");
1433	  static const std::string& kEmptyString = *new std::string("");
1434	
1435	  // NOTE: We inline the implementation of `GetNodeAttrString()` here in order
1436	  // to use the `AttrSlice::FindByString()` overload, which does a more
1437	  // efficient map lookup (instead of a linear scan) when the attribute name is
1438	  // already a `const string&`.
1439	  const AttrValue* attr_value = node_attrs.FindByString(kKernelAttr);
1440	  if (attr_value == nullptr || attr_value->value_case() != AttrValue::kS)
1441	    return kEmptyString;
1442	  else
1443	    return attr_value->s();
