1447	absl::Status FindKernelRegistration(
1448	    const DeviceType& device_type, absl::string_view node_name,
1449	    bool has_experimental_debug_info,
1450	    const NodeDef_ExperimentalDebugInfo& experimental_debug_info,
1451	    absl::string_view node_op, AttrSlice node_attrs,
1452	    const KernelRegistration** reg, bool* was_attr_mismatch,
1453	    const KernelRegistry* registry = nullptr) TF_NO_THREAD_SAFETY_ANALYSIS {
1454	  *reg = nullptr;
1455	  *was_attr_mismatch = false;
1456	
1457	  const std::string& label = GetKernelLabelAttr(node_attrs);
1458	
1459	  const std::string key = Key(node_op, device_type, label);
1460	  const KernelRegistry* typed_registry =
1461	      registry ? registry : GlobalKernelRegistryTyped();
1462	  auto regs = typed_registry->registry.equal_range(key);
1463	  for (auto iter = regs.first; iter != regs.second; ++iter) {
1464	    // If there is a kernel registered for the op and device_type,
1465	    // check that the attrs match.
1466	    bool match;
1467	    TF_RETURN_IF_ERROR(KernelAttrsMatch(iter->second.def, node_attrs, &match));
1468	    if (match) {
1469	      if (*reg != nullptr) {
1470	        if ((*reg)->def.priority() == iter->second.def.priority()) {
1471	          return absl::InvalidArgumentError(absl::StrCat(
1472	              "Multiple OpKernel registrations match NodeDef at the same "
1473	              "priority '",
1474	              FormatNodeDefForError(node_name, has_experimental_debug_info,
1475	                                    experimental_debug_info),
1476	              "': '", (*reg)->def.ShortDebugString(), "' and '",
1477	              iter->second.def.ShortDebugString(), "'"));
1478	        } else if ((*reg)->def.priority() > iter->second.def.priority()) {
1479	          continue;
1480	        }
1481	        // iter->second's priority is higher than *reg.
1482	      }
1483	      *reg = &iter->second;
1484	    } else {
1485	      *was_attr_mismatch = true;
1486	    }
1487	  }
1488	  // Check if no device specific registrations found. If not, try finding a
1489	  // default kernel.
1490	  if (*reg == nullptr &&
1491	      !IsSymbolicExecutionDevice(device_type.type_string())) {
1492	    const std::string default_key = Key(node_op, DEVICE_DEFAULT, label);
1493	    auto regs = typed_registry->registry.equal_range(default_key);
1494	    for (auto iter = regs.first; iter != regs.second; ++iter) {
1495	      // If there is a kernel registered for the op and device_type,
1496	      // check that the attrs match.
1497	      bool match;
1498	      TF_RETURN_IF_ERROR(
1499	          KernelAttrsMatch(iter->second.def, node_attrs, &match));
1500	      if (match) {
1501	        if (*reg != nullptr) {
1502	          return absl::InvalidArgumentError(absl::StrCat(
1503	              "Multiple Default OpKernel registrations match NodeDef '",
1504	              FormatNodeDefForError(node_name, has_experimental_debug_info,
1505	                                    experimental_debug_info),
1506	              "': '", (*reg)->def.ShortDebugString(), "' and '",
1507	              iter->second.def.ShortDebugString(), "'"));
1508	        }
1509	        *reg = &iter->second;
1510	      } else {
1511	        *was_attr_mismatch = true;
1512	      }
1513	    }
1514	
1515	    if (*reg != nullptr) {
1516	      VLOG(1) << "No device-specific kernels found for NodeDef '"
1517	              << FormatNodeDefForError(node_name, has_experimental_debug_info,
1518	                                       experimental_debug_info)
1519	              << "'"
1520	              << "Will fall back to a default kernel." << std::endl;
1521	    }
