357	// Partial specialization of BinaryFunctor<Device=CPUDevice, Functor, NDIMS>
358	// for functors with no error checking.
359	template <typename Functor, int NDIMS>
360	struct BinaryFunctor<CPUDevice, Functor, NDIMS, false> {
361	  void operator()(const CPUDevice& d, typename Functor::tout_type out,
362	                  typename Functor::tin_type in0,
363	                  typename Functor::tin_type in1, bool* error) {
364	    Assign(d, out, in0.binaryExpr(in1, typename Functor::func()));
365	  }
366	
367	  void Left(const CPUDevice& d, typename Functor::tout_type out,
368	            typename Functor::tscalar_type scalar,
369	            typename Functor::tin_type in, bool* error) {
370	    typedef typename Functor::out_type Tout;
371	    typedef typename Functor::in_type Tin;
372	    typedef typename Functor::func Binary;
373	    typedef typename Eigen::internal::scalar_left<Tout, Tin, Binary> Unary;
374	    Assign(d, out, in.unaryExpr(Unary(scalar.data())));
375	  }
376	
377	  void Right(const CPUDevice& d, typename Functor::tout_type out,
378	             typename Functor::tin_type in,
379	             typename Functor::tscalar_type scalar, bool* error) {
380	    typedef typename Functor::out_type Tout;
381	    typedef typename Functor::in_type Tin;
382	    typedef typename Functor::func Binary;
383	    typedef typename Eigen::internal::scalar_right<Tout, Tin, Binary> Unary;
384	    Assign(d, out, in.unaryExpr(Unary(scalar.data())));
385	  }
386	
387	  void BCast(const CPUDevice& dev,
388	             typename TTypes<typename Functor::out_type, NDIMS>::Tensor out,
389	             typename TTypes<typename Functor::in_type, NDIMS>::ConstTensor in0,
390	             typename Eigen::array<Eigen::DenseIndex, NDIMS> bcast0,
391	             typename TTypes<typename Functor::in_type, NDIMS>::ConstTensor in1,
392	             typename Eigen::array<Eigen::DenseIndex, NDIMS> bcast1,
393	             bool* error) {
394	    typename Functor::func func;
395	    if (AllOne<NDIMS>(bcast0) && AllOne<NDIMS>(bcast1)) {
396	      Assign(dev, out, in0.binaryExpr(in1, func));
397	    } else if (AllOne<NDIMS>(bcast0)) {
398	      auto rhs = in1.broadcast(bcast1);
399	      Assign(dev, out, in0.binaryExpr(rhs, func));
400	    } else if (AllOne<NDIMS>(bcast1)) {
401	      auto lhs = in0.broadcast(bcast0);
402	      Assign(dev, out, lhs.binaryExpr(in1, func));
403	    } else {
404	      auto lhs = in0.broadcast(bcast0);
405	      auto rhs = in1.broadcast(bcast1);
406	      Assign(dev, out, lhs.binaryExpr(rhs, func));
407	    }
408	  }
409	};
