411	// Partial specialization of BinaryFunctor<Device=CPUDevice, Functor, 2>
412	// for functors with no error checking.
413	template <typename Functor>
414	struct BinaryFunctor<CPUDevice, Functor, 2, false> {
415	  enum { NDIMS = 2 };
416	
417	  void operator()(const CPUDevice& d, typename Functor::tout_type out,
418	                  typename Functor::tin_type in0,
419	                  typename Functor::tin_type in1, bool* error) {
420	    Assign(d, out, in0.binaryExpr(in1, typename Functor::func()));
421	  }
422	
423	  void Left(const CPUDevice& d, typename Functor::tout_type out,
424	            typename Functor::tscalar_type scalar,
425	            typename Functor::tin_type in, bool* error) {
426	    typedef typename Functor::out_type Tout;
427	    typedef typename Functor::in_type Tin;
428	    typedef typename Functor::func Binary;
429	    typedef typename Eigen::internal::scalar_left<Tout, Tin, Binary> Unary;
430	    Assign(d, out, in.unaryExpr(Unary(scalar.data())));
431	  }
432	
433	  void Right(const CPUDevice& d, typename Functor::tout_type out,
434	             typename Functor::tin_type in,
435	             typename Functor::tscalar_type scalar, bool* error) {
436	    typedef typename Functor::out_type Tout;
437	    typedef typename Functor::in_type Tin;
438	    typedef typename Functor::func Binary;
439	    typedef typename Eigen::internal::scalar_right<Tout, Tin, Binary> Unary;
440	    Assign(d, out, in.unaryExpr(Unary(scalar.data())));
441	  }
442	
443	  inline Eigen::IndexList<Eigen::DenseIndex, Eigen::type2index<1>> NByOne(
444	      Eigen::DenseIndex n) {
445	    Eigen::IndexList<Eigen::DenseIndex, Eigen::type2index<1>> ret;
446	    ret.set(0, n);
447	    return ret;
448	  }
449	  inline Eigen::IndexList<Eigen::type2index<1>, Eigen::DenseIndex> OneByM(
450	      Eigen::DenseIndex m) {
451	    Eigen::IndexList<Eigen::type2index<1>, Eigen::DenseIndex> ret;
452	    ret.set(1, m);
453	    return ret;
454	  }
455	
456	  void BCast(const CPUDevice& dev,
457	             typename TTypes<typename Functor::out_type, NDIMS>::Tensor out,
458	             typename TTypes<typename Functor::in_type, NDIMS>::ConstTensor in0,
459	             typename Eigen::array<Eigen::DenseIndex, NDIMS> bcast0,
460	             typename TTypes<typename Functor::in_type, NDIMS>::ConstTensor in1,
461	             typename Eigen::array<Eigen::DenseIndex, NDIMS> bcast1,
462	             bool* error) {
463	    typedef typename Functor::in_type T;
464	    typename Functor::func func;
465	    if (Functor::use_bcast_optimization && use_bcast_optimization<T>::value) {
466	      // Optimize for speed by using Eigen::type2index and avoid
467	      // .broadcast() when we know it's a no-op.
468	      //
469	      // Here, we need to handle 6 cases depending on how many "1"
470	      // exist in in0 and in1's shapes (4 numbers in total). It's not
471	      // possible that two shapes have more than 2 1s because those
472	      // are simplified to NDIMS==1 case.
473	      //
474	      // Because this optimization increases the binary size for each
475	      // Functor (+, -, *, /, <, <=, etc.), type and ndim combination.
476	      // we only apply such optimization for selected ops/types/ndims.
477	      //
478	      // Because NDIMS, Functor::use_broadcast_optimization and
479	      // use_broadcast_optimization<T> are compile-time constant, gcc
480	      // does a decent job avoiding generating code when conditions
481	      // are not met.
482	      const Eigen::DenseIndex a = in0.dimension(0);  // in0 is shape [a, b]
483	      const Eigen::DenseIndex b = in0.dimension(1);
484	      const Eigen::DenseIndex c = in1.dimension(0);  // in1 is shape [c, d]
485	      const Eigen::DenseIndex d = in1.dimension(1);
486	      if ((a == 1) && (d == 1)) {
487	        auto lhs = in0.reshape(OneByM(b)).broadcast(NByOne(c));
488	        auto rhs = in1.reshape(NByOne(c)).broadcast(OneByM(b));
489	        Assign(dev, out, lhs.binaryExpr(rhs, func));
490	        return;
491	      }
492	      if ((b == 1) && (c == 1)) {
493	        auto lhs = in0.reshape(NByOne(a)).broadcast(OneByM(d));
494	        auto rhs = in1.reshape(OneByM(d)).broadcast(NByOne(a));
495	        Assign(dev, out, lhs.binaryExpr(rhs, func));
496	        return;
497	      }
498	      if (a == 1) {
499	        auto lhs = in0.reshape(OneByM(b)).broadcast(NByOne(c));
500	        auto rhs = in1;
501	        Assign(dev, out, lhs.binaryExpr(rhs, func));
502	        return;
503	      }
504	      if (b == 1) {
505	        auto lhs = in0.reshape(NByOne(a)).broadcast(OneByM(d));
506	        auto rhs = in1;
507	        Assign(dev, out, lhs.binaryExpr(rhs, func));
508	        return;
509	      }
510	      if (c == 1) {
511	        auto lhs = in0;
512	        auto rhs = in1.reshape(OneByM(d)).broadcast(NByOne(a));
513	        Assign(dev, out, lhs.binaryExpr(rhs, func));
514	        return;
515	      }
516	      if (d == 1) {
517	        auto lhs = in0;
518	        auto rhs = in1.reshape(NByOne(c)).broadcast(OneByM(b));
519	        Assign(dev, out, lhs.binaryExpr(rhs, func));
520	        return;
521	      }
522	
523	      const bool bcast0_all_one = AllOne<NDIMS>(bcast0);
524	      const bool bcast1_all_one = AllOne<NDIMS>(bcast1);
525	      if (bcast0_all_one && !bcast1_all_one) {
526	        auto lhs = in0;  // No need to do broadcast for in0
527	        auto rhs = in1.broadcast(bcast1);
528	        Assign(dev, out, lhs.binaryExpr(rhs, func));
529	        return;
530	      }
531	
532	      if (!bcast0_all_one && bcast1_all_one) {
533	        auto lhs = in0.broadcast(bcast0);
534	        auto rhs = in1;  // No need to do broadcast for in1
535	        Assign(dev, out, lhs.binaryExpr(rhs, func));
536	        return;
537	      }
538	    }
539	
540	    // Fallback path. Always works and probably slower.
541	    auto lhs = in0.broadcast(bcast0);
542	    auto rhs = in1.broadcast(bcast1);
543	    Assign(dev, out, lhs.binaryExpr(rhs, func));
544	  }
545	};
546	
547	// Version of BinaryFunctor with error handling.
548	template <typename Functor, int NDIMS>
549	struct BinaryFunctor<CPUDevice, Functor, NDIMS, true> {
550	  void operator()(const CPUDevice& d, typename Functor::tout_type out,
551	                  typename Functor::tin_type in0,
552	                  typename Functor::tin_type in1, bool* error) {
553	    Assign(d, out, in0.binaryExpr(in1, typename Functor::func(error)));
554	  }
555	
556	  void Left(const CPUDevice& d, typename Functor::tout_type out,
557	            typename Functor::tscalar_type scalar,
558	            typename Functor::tin_type in, bool* error) {
559	    typedef typename Functor::out_type Tout;
560	    typedef typename Functor::in_type Tin;
561	    typedef typename Functor::func Binary;
562	    typedef typename Eigen::internal::scalar_left<Tout, Tin, Binary> Unary;
563	    Assign(d, out, in.unaryExpr(Unary(scalar.data(), error)));
564	  }
565	
566	  void Right(const CPUDevice& d, typename Functor::tout_type out,
567	             typename Functor::tin_type in,
568	             typename Functor::tscalar_type scalar, bool* error) {
569	    typedef typename Functor::out_type Tout;
570	    typedef typename Functor::in_type Tin;
571	    typedef typename Functor::func Binary;
572	    typedef typename Eigen::internal::scalar_right<Tout, Tin, Binary> Unary;
573	    Assign(d, out, in.unaryExpr(Unary(scalar.data(), error)));
574	  }
575	
576	  void BCast(const CPUDevice& dev,
577	             typename TTypes<typename Functor::out_type, NDIMS>::Tensor out,
578	             typename TTypes<typename Functor::in_type, NDIMS>::ConstTensor in0,
579	             typename Eigen::array<Eigen::DenseIndex, NDIMS> bcast0,
580	             typename TTypes<typename Functor::in_type, NDIMS>::ConstTensor in1,
581	             typename Eigen::array<Eigen::DenseIndex, NDIMS> bcast1,
582	             bool* error) {
583	    typename Functor::func func(error);
584	    auto lhs = in0.broadcast(bcast0);
585	    auto rhs = in1.broadcast(bcast1);
586	    Assign(dev, out, lhs.binaryExpr(rhs, func));
587	  }
588	};
589	
590	// Partial specialization of UnaryFunctor<Device=CPUDevice, Functor>.
591	template <typename Functor>
592	struct UnaryFunctor<CPUDevice, Functor> {
593	  void operator()(const CPUDevice& d, typename Functor::tout_type out,
594	                  typename Functor::tin_type in) {
595	    Assign(d, out, in.unaryExpr(typename Functor::func()));
596	  }
597	};
598	
599	template <typename Functor, typename Targ>
600	struct UnaryFunctorWithArg<CPUDevice, Functor, Targ> {
601	  void operator()(const CPUDevice& d, typename Functor::tout_type out,
602	                  typename Functor::tin_type in, Targ val) {
603	    Assign(d, out, in.unaryExpr(typename Functor::func(val)));
604	  }
605	};
606	
607	// Partial specialization of ApproximateEqual<Device=CPUDevice, T>.
608	template <typename T>
609	struct ApproximateEqual<CPUDevice, T> {
610	  void operator()(const CPUDevice& d, typename TTypes<T>::ConstFlat x,
611	                  typename TTypes<T>::ConstFlat y, T tolerance,
612	                  typename TTypes<bool>::Flat z) {
613	    auto diff = x - y;
614	    z.device(d) = diff.abs() <= tolerance;
615	  }
616	};
617	
618	}  // end namespace functor
619	
620	#define REGISTER(OP, D, N, F, T)                                             \
621	  REGISTER_KERNEL_BUILDER(Name(N).Device(DEVICE_##D).TypeConstraint<T>("T"), \
622	                          OP<D##Device, F<T>>);
623	
624	#define REGISTER_VARIANT(OP, D, N, ENUM)                       \
