642	#define REGISTER5(OP, D, N, F, T0, T1, T2, T3, T4) REGISTER(OP, D, N, F, T0)
643	#define REGISTER6(OP, D, N, F, T0, T1, T2, T3, T4, T5) REGISTER(OP, D, N, F, T0)
644	#define REGISTER7(OP, D, N, F, T0, T1, T2, T3, T4, T5, T6) \
